/* The value a previous region left on the memory stack, per storage class:
 * the leaf the next region's first consumer takes as its child. */
static const uint16_t jav_carried_sig[6] = { 235, 236, 237, 238, 239, 240, };

/* Can a value of this class live in a cache slot? A managed reference
 * cannot: it belongs on the operand stack, where the collector looks for
 * roots and, because the collector moves objects, where it rewrites them.
 * A register has no address to rewrite. */
static const uint8_t jav_class_cacheable[7] = { 1, 1, 1, 1, 1, 0, 0, };

/* Slots a value of this class occupies. Two for a v128 — the state is
 * a count of SLOTS, so an item may spend one or two of them. */
static const uint8_t jav_class_width[7] = { 1, 1, 1, 1, 2, 1, 1, };

/* The class a §7.6 value type is HELD in. WVT_BOT has none — it is the
 * validator's "any type" and no register answers it. */
static inline uint8_t jav_sclass_of_valtype(jav_valtype_t t) {
    switch (t) {
    case WVT_I32:  return JSC_I32;
    case WVT_I64:  return JSC_I64;
    case WVT_F32:  return JSC_F32;
    case WVT_F64:  return JSC_F64;
    case WVT_V128: return JSC_V128;
    case WVT_REF: case WVT_REF_NN: return JSC_REF;
    default:       return JSC_COUNT;
    }
}

